+
+/* Calm, readable controls and a slightly softer panel hierarchy. */
+:focus-visible{outline:2px solid var(--mint);outline-offset:3px}
+.sound-button{width:auto;min-width:104px;height:36px;padding:0 11px;display:inline-flex;align-items:center;justify-content:center;gap:8px;background:#111b29;color:#a6b5c8;font-size:12px;transition:background .18s,border-color .18s,color .18s}
+.sound-button>span:first-child{color:var(--mint);font-size:16px;line-height:1}
+.sound-button:hover,.sound-button[aria-pressed="true"]{background:#18332f;border-color:#397761;color:#d7ffec}
+.resource-bar{background:linear-gradient(180deg,#0d1420,#0b111b)}
+.resource-card{min-width:145px}
+.resource-value{font-variant-numeric:tabular-nums}
+.planet-card{border-color:#29394d;background:linear-gradient(110deg,#141f2e 0%,#111b29 53%,#101a29 100%);box-shadow:0 18px 55px #0003}
+.planet-copy .eyebrow{letter-spacing:1.05px}
+.planet-description{max-width:290px;line-height:1.6}
+.planet-tags span{background:#111b29a8}
+.section-heading h2{font-size:21px}
+.panel,.detail-card{box-shadow:0 10px 28px #00000012}
+.panel-heading{background:#121c2a}
+.panel-heading h3{font-size:13px}
+.panel-heading small{font-size:8px}
+.panel-action{min-height:44px}
+.online-note{white-space:nowrap}
+.upgrade-row{min-height:82px}
+button:not(:disabled){-webkit-tap-highlight-color:transparent}
+.nav-item,.upgrade-buy button,.primary-button{transition:background .18s,border-color .18s,transform .18s,opacity .18s}
+.nav-item:active,.upgrade-buy button:active:not(:disabled),.primary-button:active:not(:disabled){transform:translateY(1px)}
+.footer-note{padding-bottom:max(4px,env(safe-area-inset-bottom))}
+@media(max-width:720px){
+  .sound-button{min-width:92px;height:35px;padding:0 9px;font-size:11px}
+  .planet-card{box-shadow:0 12px 32px #0003}
+  .planet-copy{padding-top:19px}
+  .planet-description{max-width:190px}
+  .overview-grid,.multi-grid{grid-template-columns:minmax(0,1fr)}
+  .panel-heading{height:47px}
+  .upgrade-row{min-height:78px}
+  .footer-note{line-height:1.5}
+}
+@media(prefers-reduced-motion:reduce){*,*::before,*::after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}
